    --bs-btn-active-bg: var(--primary-active);
    --bs-btn-active-border-color: var(--primary-active);
    --bs-btn-disabled-color: var(--text-on-primary);
    --bs-btn-disabled-bg: var(--primary-disabled);
    --bs-btn-disabled-border-color: var(--primary-disabled);
}

.btn-secondary {
    --bs-btn-color: var(--text-secondary);
    --bs-btn-bg: var(--surface);
    --bs-btn-border-color: var(--border-control);
    --bs-btn-hover-color: var(--text-primary);
    --bs-btn-hover-bg: var(--surface-secondary);
    --bs-btn-hover-border-color: var(--border-control-hover);
    --bs-btn-active-color: var(--text-primary);
    --bs-btn-active-bg: var(--border-subtle);
    --bs-btn-active-border-color: var(--border-control-active);
    --bs-btn-disabled-color: var(--text-disabled);
    --bs-btn-disabled-bg: var(--surface-secondary);
    --bs-btn-disabled-border-color: var(--border-disabled);
}

.btn-danger {
    --bs-btn-bg: var(--danger);
    --bs-btn-border-color: var(--danger);
    --bs-btn-hover-bg: var(--danger-hover);
    --bs-btn-hover-border-color: var(--danger-hover);
    --bs-btn-active-bg: var(--danger-active);
    --bs-btn-active-border-color: var(--danger-active);
}

.form-control,
.form-select {
    min-height: var(--control-height);
    color: var(--text-secondary);
    border-color: var(--border-control);
    border-radius: var(--radius-control);
    background-color: var(--surface);
    font-size: 1rem;
    line-height: 1.5rem;
}

.form-control:hover,
.form-select:hover {
    border-color: var(--border-control-hover);
}

.form-control:focus,
.form-select:focus {
    color: var(--text-primary);
    border-color: var(--primary);
    box-shadow: 0 0 0 var(--focus-ring-width) var(--primary-focus);
}

.form-control::placeholder {
    color: var(--text-placeholder);
}

.form-control.is-invalid,
.form-select.is-invalid {
    border-color: var(--danger);
}

.form-control.is-invalid:focus,
.form-select.is-invalid:focus {
    box-shadow: 0 0 0 var(--focus-ring-width) var(--danger-focus);
}

.react-datepicker {
    border-color: var(--border-default) !important;
    border-radius: var(--radius-card) !important;
    box-shadow: var(--shadow-dropdown);
    font-family: var(--font-family) !important;
}

.react-datepicker__header {
    background: var(--table-header-bg) !important;
    border-bottom-color: var(--border-subtle) !important;
}

.react-datepicker__day--selected,
.react-datepicker__day--keyboard-selected {
    background: var(--primary) !important;
}

@media (prefers-reduced-motion: reduce) {
    html { scroll-behavior: auto; }
    *, *::before, *::after {
        scroll-behavior: auto !important;
        transition-duration: .01ms !important;
        animation-duration: .01ms !important;
        animation-iteration-count: 1 !important;
    }
}
