import { DEFAULT_REGIONAL_LOCALE } from "../constants/languages";
const LENS_SIZE = 240;
const MAGNIFICATION = 2;
const extensionByMime = {
    "image/jpeg": "jpg",
    "image/png": "png",
    "image/webp": "webp",
    "image/gif": "gif",
    "application/pdf": "pdf"
};
function clamp(value, minimum, maximum) {
    return Math.min(Math.max(value, minimum), maximum);
}
export function formatReceiptFileSize(bytes) {
    if (bytes < 1024)
        return `${bytes} Б`;
    const value = bytes < 1024 * 1024 ? bytes / 1024 : bytes / (1024 * 1024);
    const unit = bytes < 1024 * 1024 ? "КБ" : "МБ";
    return `${new Intl.NumberFormat(DEFAULT_REGIONAL_LOCALE, {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    }).format(value)} ${unit}`;
}
export function getReceiptFileName(dateValue, mime) {
    const date = new Date(dateValue);
    const datePart = Number.isNaN(date.getTime()) ? "receipt" : date.toISOString().slice(0, 10);
    return `receipt-${datePart}.${extensionByMime[mime] || "bin"}`;
}
export function getReceiptLensState(clientX, clientY, image, container) {
    const imageRect = image.getBoundingClientRect();
    const containerRect = container.getBoundingClientRect();
    if (!imageRect.width || !imageRect.height)
        return null;
    const x = clamp(clientX - imageRect.left, 0, imageRect.width);
    const y = clamp(clientY - imageRect.top, 0, imageRect.height);
    const size = Math.min(LENS_SIZE, imageRect.width, imageRect.height);
    const backgroundWidth = imageRect.width * MAGNIFICATION;
    const backgroundHeight = imageRect.height * MAGNIFICATION;
    return {
        backgroundHeight,
        backgroundPositionX: size / 2 - x * MAGNIFICATION,
        backgroundPositionY: size / 2 - y * MAGNIFICATION,
        backgroundWidth,
        left: imageRect.left - containerRect.left + x - size / 2,
        size,
        top: imageRect.top - containerRect.top + y - size / 2
    };
}
