    --radius-modal: 0.75rem;
    --control-height: 2.75rem;
    --control-height-compact: 2.25rem;
    --sidebar-width: 14rem;
    --sidebar-collapsed-width: 4.75rem;
    --sidebar-mobile-width: 15.25rem;
    --shadow-card: 0 0.0625rem 0.1875rem rgba(16, 24, 40, 0.06);
    --shadow-dropdown: 0 0.5rem 1.5rem rgba(16, 24, 40, 0.12);
    --shadow-modal: 0 1.25rem 3rem rgba(16, 24, 40, 0.22);
    --shadow-zoom-hint: 0 0.1875rem 0.625rem rgba(16, 24, 40, 0.18);
