import { PaymentMethodT } from "../types";
let draftKey = 0;
export function createReceiptItemKey(prefix = "item") {
    draftKey += 1;
    return `${prefix}-${Date.now()}-${draftKey}`;
}
function toInputValue(value) {
    return value === null || typeof value === "undefined" ? "" : String(value);
}
export function getUtcDateTimeParts(value) {
    const date = new Date(value);
    if (Number.isNaN(date.getTime()))
        return { date: "", time: "" };
    const pad = (part) => String(part).padStart(2, "0");
    return {
        date: `${date.getUTCFullYear()}-${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())}`,
        time: `${pad(date.getUTCHours())}:${pad(date.getUTCMinutes())}`
    };
}
export function combineUtcDateTime(dateValue, timeValue) {
    const value = `${dateValue}T${timeValue}:00.000Z`;
    const date = new Date(value);
    if (Number.isNaN(date.getTime()))
        return null;
    if (getUtcDateTimeParts(date.toISOString()).date !== dateValue
        || getUtcDateTimeParts(date.toISOString()).time !== timeValue) {
        return null;
    }
    return date.toISOString();
}
export function createReceiptDraft(receipt, descriptions, getDescriptionKey) {
    const { date, time } = getUtcDateTimeParts(receipt.date);
    return {
        ...receipt,
        date,
        time,
        totalPrice: toInputValue(receipt.totalPrice),
        items: receipt.items.map((item, index) => ({
            key: createReceiptItemKey(`${receipt._id}-${index}`),
            name: item.name,
            count: toInputValue(item.count),
            weight: toInputValue(item.weight),
            pricePerKilo: toInputValue(item.pricePerKilo),
            price: toInputValue(item.price),
            description: descriptions[getDescriptionKey(item.name)] || item.description || ""
        }))
    };
}
export function parseDecimal(value) {
    const normalized = value.trim().replace(",", ".");
    if (!normalized || !/^-?\d+(\.\d+)?$/.test(normalized))
        return null;
    const number = Number(normalized);
    return Number.isFinite(number) ? number : null;
}
function optionalDecimal(value) {
    if (!value.trim())
        return null;
    return parseDecimal(value);
}
export function validateReceiptDraft(draft) {
    const fields = {};
    const items = {};
    if (!draft.shopName.trim())
        fields.shopName = "Укажите магазин";
    if (!draft.date || !combineUtcDateTime(draft.date, draft.time || "00:00")) {
        fields.date = "Укажите корректную дату";
    }
    if (!draft.time || !combineUtcDateTime(draft.date || "1970-01-01", draft.time)) {
        fields.time = "Укажите корректное время";
    }
    if (!Object.values(PaymentMethodT).includes(draft.paymentMethod)) {
        fields.paymentMethod = "Выберите способ оплаты";
    }
    const total = parseDecimal(draft.totalPrice);
    if (total === null || total < 0)
        fields.totalPrice = "Введите сумму не меньше нуля";
    draft.items.forEach((item) => {
        const rowErrors = {};
        const count = parseDecimal(item.count);
        const weight = optionalDecimal(item.weight);
        const pricePerKilo = optionalDecimal(item.pricePerKilo);
        const price = parseDecimal(item.price);
        if (!item.name.trim())
            rowErrors.name = "Укажите название";
        if (count === null || count <= 0)
            rowErrors.count = "Количество должно быть больше нуля";
        if (item.weight.trim() && (weight === null || weight < 0)) {
            rowErrors.weight = "Вес не может быть отрицательным";
        }
        if (item.pricePerKilo.trim() && (pricePerKilo === null || pricePerKilo < 0)) {
            rowErrors.pricePerKilo = "Цена не может быть отрицательной";
        }
        if (price === null || price < 0)
            rowErrors.price = "Цена не может быть отрицательной";
        if (Object.keys(rowErrors).length)
            items[item.key] = rowErrors;
    });
    return { fields, items };
}
export function hasValidationErrors(errors) {
    return Object.keys(errors.fields).length > 0 || Object.keys(errors.items).length > 0;
}
export function calculateDraftItemTotal(items) {
    const minorUnits = items.reduce((total, item) => {
        const price = parseDecimal(item.price);
        return price === null ? total : total + Math.round(price * 100);
    }, 0);
    return minorUnits / 100;
}
export function serializeReceiptDraft(draft) {
    const date = combineUtcDateTime(draft.date, draft.time);
    if (!date)
        throw new Error("Invalid receipt date");
    const items = draft.items.map(({ key: _key, ...item }) => ({
        name: item.name.trim(),
        count: parseDecimal(item.count),
        weight: optionalDecimal(item.weight),
        pricePerKilo: optionalDecimal(item.pricePerKilo),
        price: parseDecimal(item.price),
        description: item.description.trim() || undefined
    }));
    return {
        _id: draft._id,
        id: draft.id,
        receiptImageId: draft.receiptImageId,
        shopName: draft.shopName.trim(),
        date,
        createdDate: draft.createdDate,
        address: draft.address.trim(),
        totalPrice: parseDecimal(draft.totalPrice),
        paymentMethod: draft.paymentMethod,
        currency: draft.currency,
        items
    };
}
export function isReceiptDraftDirty(draft, pristine) {
    return JSON.stringify(draft) !== JSON.stringify(pristine);
}
